The generators are gone (only the IF builder `mk` survived), so I'll write fresh math templates with brute-force answers. I'll use new problem types rather than the T1–T25 templates, which covers more ground: counting with divisibility, divisor counts, digit sums, modular towers, lattice points, subset sums, partitions into distinct parts, quadratic residues, Pythagorean triples, coprime residue classes, polynomial coefficients, and constrained digit strings. The target is about 120 items at roughly the earlier difficulty. Every answer is computed exactly by enumeration or DP.

```python
# Hypothesis: (setup) 12 new competition-style templates x 10 instances with brute-force answers give a fresh math confirm set
import random as _r
from math import gcd
R = _r.Random(20261112)
def t_triples():
    S = R.randint(15, 30); m = R.choice([6, 8, 9, 10, 12])
    a = sum(1 for x in range(1, S) for y in range(1, S - x) if (x * y * (S - x - y)) % m == 0)
    return f"How many ordered triples $(a, b, c)$ of positive integers satisfy $a + b + c = {S}$ and $abc$ divisible by ${m}$?", a
def t_divsum():
    N = R.randint(150, 400); k = R.choice([4, 6, 8])
    d = lambda n: sum(1 for i in range(1, n + 1) if n % i == 0)
    return f"What is the sum of all positive integers $n \\le {N}$ that have exactly ${k}$ positive divisors?", sum(n for n in range(1, N + 1) if d(n) == k)
def t_digitsum():
    N = R.randint(2000, 9999); s = R.randint(9, 20)
    return f"How many integers $n$ with $1 \\le n \\le {N}$ have digit sum equal to ${s}$?", sum(1 for n in range(1, N + 1) if sum(map(int, str(n))) == s)
def t_tower():
    a = R.choice([3, 7, 11, 13, 17]); b = R.choice([2, 3, 5]); c = R.choice([3, 4, 5, 6]); m = R.choice([100, 125, 1000, 77, 99])
    return f"Find the remainder when ${a}^{{{b}^{{{c}}}}}$ is divided by ${m}$.", pow(a, b ** c, m)
def t_lattice():
    R2 = R.randint(20, 60); A, B = R.randint(1, 3), R.randint(1, 4)
    return f"How many points $(x, y)$ with integer coordinates satisfy ${A}x^2 + {B}y^2 \\le {R2}$?", sum(1 for x in range(-60, 61) for y in range(-60, 61) if A * x * x + B * y * y <= R2)
def t_subsets():
    n = R.randint(10, 14); m = R.choice([3, 4, 5, 6, 7])
    dp = [1] + [0] * (m - 1)
    for v in range(1, n + 1): dp = [dp[j] + dp[(j - v) % m] for j in range(m)]
    return f"How many subsets of $\\{{1, 2, \\ldots, {n}\\}}$ (including the empty set) have a sum of elements divisible by ${m}$?", dp[0]
def t_distinct_parts():
    N = R.randint(20, 40); k = R.randint(8, 14)
    dp = [1] + [0] * N
    for v in range(1, k + 1):
        for s_ in range(N, v - 1, -1): dp[s_] += dp[s_ - v]
    return f"In how many ways can ${N}$ be written as a sum of distinct positive integers, each at most ${k}$? (The order of the summands does not matter.)", dp[N]
def t_qres():
    m = R.choice([120, 168, 180, 210, 240, 252, 360]); a = R.choice([1, 4, 9, 16, 25, 49])
    return f"How many integers $x$ with $0 \\le x < {m}$ satisfy $x^2 \\equiv {a} \\pmod{{{m}}}$?", sum(1 for x in range(m) if (x * x - a) % m == 0)
def t_pyth():
    H = R.randint(40, 120)
    return f"How many right triangles with positive integer side lengths have hypotenuse at most ${H}$? (Triangles that are congruent count once.)", sum(1 for a in range(1, H) for b in range(a, H) for c in [int(round((a * a + b * b) ** 0.5))] if c * c == a * a + b * b and c <= H)
def t_coprime():
    N = R.randint(300, 900); M = R.choice([30, 42, 66, 70, 105]); q = R.choice([4, 7, 9]); r = R.randint(1, q - 1)
    return f"How many integers $n$ with $1 \\le n \\le {N}$ satisfy $\\gcd(n, {M}) = 1$ and $n \\equiv {r} \\pmod{{{q}}}$?", sum(1 for n in range(1, N + 1) if gcd(n, M) == 1 and n % q == r)
def t_coef():
    n = R.randint(6, 10); k = R.randint(5, 12); c = R.choice([2, 3])
    poly = [1]
    for _ in range(n):
        new = [0] * (len(poly) + 3)
        for i_, v in enumerate(poly):
            new[i_] += v; new[i_ + 1] += c * v; new[i_ + 3] += v
        poly = new
    return f"What is the coefficient of $x^{{{k}}}$ in the expansion of $(1 + {c}x + x^3)^{{{n}}}$?", poly[k] if k < len(poly) else 0
def t_digits():
    L = R.randint(5, 7); forb = R.randint(2, 4)
    cnt_ = sum(1 for n in range(10 ** (L - 1), 10 ** L) if all(abs(int(a) - int(b)) >= forb for a, b in zip(str(n), str(n)[1:])))
    return f"How many ${L}$-digit positive integers have the property that any two adjacent digits differ by at least ${forb}$?", cnt_
gens = [t_triples, t_divsum, t_digitsum, t_tower, t_lattice, t_subsets, t_distinct_parts, t_qres, t_pyth, t_coprime, t_coef, t_digits]
new_math, seen_q = [], set()
for g_ in gens:
    made = 0
    while made < 10:
        q, a = g_()
        if q in seen_q: continue
        seen_q.add(q); new_math.append(dict(id=f'n{len(new_math):03d}', tpl=g_.__name__, q=q, ans=str(a), prompt=q + SUFFIX)); made += 1
print(len(new_math)); print([ (x['tpl'], x['ans']) for x in new_math[::10]])
print(asc(new_math[0]['prompt']))
```

